SELECT COUNT(*) 
FROM schools 
WHERE Virtual = 'F';

SELECT CAST(SUM(CASE WHEN b.bond_type = '=' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) 
FROM bond b 
WHERE b.molecule_id = 'TR008';

SELECT 
    ROUND(CAST(SUM(CASE WHEN label = '+' THEN 1 ELSE 0 END) AS REAL) / (SELECT COUNT(molecule_id) FROM molecule) * 100, 3) AS percentage
FROM molecule;

SELECT borderColor 
FROM cards 
WHERE asciiName = 'Ancestor''s Chosen';

SELECT OwnerDisplayName
FROM posts
WHERE Title = 'Eliciting priors from experts';

SELECT p.OwnerDisplayName
FROM posts AS p
WHERE p.Title = 'Open source tools for visualizing multi-dimensional data';

SELECT COUNT(*) 
FROM superhero 
WHERE full_name IS NULL;

SELECT power_name
FROM superpower
WHERE id = (SELECT id FROM superhero WHERE superhero_name = 'Abomination' LIMIT 1);

SELECT CAST(SUM(CASE WHEN L.UA <= '8.0' AND P.SEX = 'M' THEN 1 ELSE 0 END) AS FLOAT) / NULLIF(CAST(SUM(CASE WHEN L.UA <= '6.5' AND P.SEX = 'F' THEN 1 ELSE 0 END) AS FLOAT), 0) AS ratio;
FROM Patient P
JOIN Laboratory L ON P.ID = L.ID;

SELECT (SUM(CASE WHEN PLT < 100 THEN 1 ELSE 0 END) - SUM(CASE WHEN PLT > 400 THEN 1 ELSE 0 END)) AS difference
FROM Laboratory
WHERE PLT <= 100 OR PLT >= 400;

SELECT notes 
FROM income 
WHERE date_received = '2019-09-14' AND source = 'Fundraising';

SELECT SUM(e.cost) AS total_cost
FROM expense e
WHERE e.expense_description = 'Pizza';

SELECT MAX(Consumption) 
FROM yearmonth 
WHERE Date LIKE '2012_%';

SELECT MIN(Time), MAX(Time)
FROM transactions_1k
WHERE GasStationID = 11;

SELECT 
    CAST(SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) AS FLOAT) / COUNT(*) * 100 AS percentage_eur_customers
FROM customers;
